        if unit_weight <= 0:
            raise ValueError("unit_weight_grams must be positive")
        if unit_weight > max_parcel_grams:
            raise ValueError(f"single unit of {sku} exceeds max_parcel_grams")
        if sku in sku_weights and sku_weights[sku] != unit_weight:
            raise ValueError(f"SKU {sku} has inconsistent unit weights")
        sku_weights[sku] = unit_weight
        merged[sku] = merged.get(sku, 0) + qty
    sorted_skus = sorted(merged.keys(), key=lambda s: (-sku_weights[s], s))
    bins: List[Dict[str, int]] = []
    remaining: List[int] = []
    for sku in sorted_skus:
        qty = merged[sku]
        w = sku_weights[sku]
        left = qty
        for i in range(len(bins)):
            if left == 0:
                break
            can_fit = remaining[i] // w
            take = min(can_fit, left)
            if take > 0:
                bins[i][sku] = bins[i].get(sku, 0) + take
                remaining[i] -= take * w
                left -= take
        while left > 0:
            can_fit = max_parcel_grams // w
            take = min(can_fit, left)
            bins.append({sku: take})
            remaining.append(max_parcel_grams - take * w)
            left -= take
    return bins
